"use strict";(self.webpackChunkcarlrocks_com=self.webpackChunkcarlrocks_com||[]).push([[9151],{80423:e=>{e.exports=JSON.parse('{"label":"Music","permalink":"/docs/tags/music","allTagsPath":"/docs/tags","count":6,"items":[{"id":"Profolio/Music/HoffmanSchumann/index","title":"Hoffman, Schumann, and the Romantic Artists","description":"&nbsp;&nbsp;&nbsp;&nbsp;\\tAs a student majoring in both music and computer science, I have always believed that different subjects share the common values and influence each other intrinsically and extrinsically. Even in the modern age, technology has been dominating the world and changing the way people live; good products are all inspired and influenced by art, culture, and mentality. However, back to the Romantic era, the mutually connected influences between music and literature are even more tight. Robert Schumann and E.T.A Hoffman are both great artists in the 19th century. Even though they were not close friends proved by any historical material, they shared the same spiritual connection between each other in the struggle against Biedermeier and ignorance over good and creative arts among the middle class. Comparing Hoffman\'s The Life and Opinions of Kater Murr, and Schumann\'s Kreisleriana, which Schumann was inspired by Hoffman\'s writing of the character Kreisler, there are many interesting aspects to target and discuss. I think the most interesting crossing aspects Schumann and Hoffman share are Style, Unusual Form, and Spirit.","permalink":"/docs/Profolio/Music/HoffmanSchumann/"},{"id":"Profolio/Music/Boulevard/index","title":"Music Analysis of \\"Sunset Boulevard\\"","description":"Introduction","permalink":"/docs/Profolio/Music/Boulevard/"},{"id":"Profolio/Photography/2019/PaulMcCartney/index","title":"Paul McCartney Refreshen Up Concert","description":"Original pictures are here","permalink":"/docs/Profolio/Photography/2019/PaulMcCartney/"},{"id":"Profolio/Music/ProkofievByHimself/index","title":"Prokofiev By Himself","description":"I was browsering on Apple Music recently, and found this album :","permalink":"/docs/Profolio/Music/ProkofievByHimself/"},{"id":"Profolio/Music/SchubertBetrogen/index","title":"Schubert\u2019s \u201cDie liebe hat gelogen\u201d","description":"Introduction","permalink":"/docs/Profolio/Music/SchubertBetrogen/"},{"id":"Profolio/Music/Castrati/index","title":"The Castrati Phenomenon In 17th Century Opera","description":"Intro","permalink":"/docs/Profolio/Music/Castrati/"}]}')}}]);